    c=m.get('content')
    if t=='user':
        if isinstance(c,str):
            out.append(f"[{ts}] USER: {c[:3000]}")
        elif isinstance(c,list):
            for b in c:
                if b.get('type')=='text':
                    out.append(f"[{ts}] USER: {b['text'][:3000]}")
                elif b.get('type')=='tool_result':
                    cc=b.get('content')
                    if isinstance(cc,list):
                        s=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    else: s=str(cc)
                    out.append(f"[{ts}]   RESULT: {s[:1200]}")
    elif t=='assistant':
        for b in (c or []):
            if b.get('type')=='text':
                out.append(f"[{ts}] A: {b['text'][:3000]}")
            elif b.get('type')=='tool_use':
                n=b.get('name'); inp=b.get('input',{})
                if n=='Bash':
                    out.append(f"[{ts}] TOOL Bash: {str(inp.get('command'))[:900]}")
                elif n in ('Read',):
                    out.append(f"[{ts}] TOOL Read: {inp.get('file_path')} {inp.get('offset','')} {inp.get('limit','')}")
                elif n in ('Write',):
                    out.append(f"[{ts}] TOOL Write: {inp.get('file_path')} ({len(str(inp.get('content','')))} chars)")
                elif n=='Edit':
                    out.append(f"[{ts}] TOOL Edit: {inp.get('file_path')} | old={str(inp.get('old_string'))[:160]!r} new={str(inp.get('new_string'))[:160]!r}")
                elif n in ('Grep','Glob'):
                    out.append(f"[{ts}] TOOL {n}: {str(inp)[:400]}")
                else:
                    out.append(f"[{ts}] TOOL {n}: {str(inp)[:900]}")
    elif t=='attachment':
        out.append(f"[{ts}] ATTACH: {str(r)[:300]}")
    elif t=='system':
        out.append(f"[{ts}] SYS: {str(r.get('content'))[:400]}")
print('\n'.join(out))
